// ===================================================================
// 제4장 정식 기말고사 (v5.9): 차세대 은하 연합 통신 노드
// ===================================================================
//
// 설계 철학:
// "이 시스템은 당신이 배운 모든 것의 증명입니다."
//
// 포함된 기술:
// v5.0: 구조체 정의
// v5.1: 메서드와 impl
// v5.2: 열거형
// v5.3: Option과 Result
// v5.4: 패턴 매칭
// v5.5: 벡터와 동적 데이터
// v5.7: 해시맵
// v5.8: 데이터 모델링 통합
// v5.8.1: 제네릭 설계
// v5.8.2: 뉴타입과 타입 에일리어스
//
// 이 코드가 완벽하게 컴파일되고 작동한다면,
// 당신은 공식적으로 '데이터 아키텍트'입니다.
//
// ===================================================================

use std::collections::HashMap;

// ===================================================================
// 1단계: 데이터 정의 (v5.0, v5.2, v5.8.2)
// ===================================================================

/// 신호 타입 열거형 (v5.2)
/// 세 가지 신호 상태를 명확히 정의합니다.
#[derive(Debug, Clone, PartialEq)]
enum SignalType {
    /// 정상 신호 (비콘)
    Beacon,
    /// 데이터 전송
    Data(String),
    /// 긴급 신호 (심각도 0-255)
    Emergency(u8),
}

impl SignalType {
    /// 신호가 긴급인지 판단
    fn is_emergency(&self) -> bool {
        matches!(self, SignalType::Emergency(_))
    }

    /// 신호 심각도 반환 (0-255, 없으면 0)
    fn severity(&self) -> u8 {
        match self {
            SignalType::Emergency(level) => *level,
            _ => 0,
        }
    }
}

/// NodeID 뉴타입 (v5.8.2)
/// u32를 감싸서 ID의 의미를 명확히 하고, 혼동을 방지합니다.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct NodeID(u32);

impl NodeID {
    /// NodeID 생성 (유효성 검증)
    fn new(id: u32) -> Result<Self, String> {
        if id > 0 {
            Ok(NodeID(id))
        } else {
            Err("NodeID는 양수여야 합니다".to_string())
        }
    }

    /// 내부 값 반환
    fn value(&self) -> u32 {
        self.0
    }
}

/// 통신 노드 구조체 (v5.0)
#[derive(Debug, Clone)]
struct Node {
    id: NodeID,
    location: String,
    last_signal: SignalType,
}

/// Node 메서드 구현 (v5.1)
impl Node {
    /// 새로운 노드 생성
    fn new(id: NodeID, location: String) -> Self {
        Node {
            id,
            location,
            last_signal: SignalType::Beacon,
        }
    }

    /// 신호 갱신
    fn update_signal(&mut self, signal: SignalType) {
        self.last_signal = signal;

