     1→/**
     2→ * V3 Lexer (어휘 분석기)
     3→ *
     4→ * V3 소스 코드를 토큰으로 변환
     5→ * - V3 키워드 인식 (ARR, INT, STR, IF, FOR 등)
     6→ * - Python 스타일 들여쓰기 (INDENT/DEDENT)
     7→ * - 에러 위치 추적
     8→ */
     9→
    10→export enum V3TokenType {
    11→  // 리터럴
    12→  NUMBER = 'NUMBER',
    13→  STRING = 'STRING',
    14→  BOOL = 'BOOL',
    15→
    16→  // 식별자 & 키워드
    17→  IDENTIFIER = 'IDENTIFIER',
    18→  KEYWORD = 'KEYWORD',
    19→
    20→  // 연산자
    21→  PLUS = 'PLUS',
    22→  MINUS = 'MINUS',
    23→  STAR = 'STAR',
    24→  SLASH = 'SLASH',
    25→  EQ = 'EQ',
    26→  NE = 'NE',
    27→  LT = 'LT',
    28→  LE = 'LE',
    29→  GT = 'GT',
    30→  GE = 'GE',
    31→  ASSIGN = 'ASSIGN',
    32→  AND = 'AND',
    33→  OR = 'OR',
    34→
    35→  // 기호
    36→  LPAREN = 'LPAREN',      // (
    37→  RPAREN = 'RPAREN',      // )
    38→  LBRACKET = 'LBRACKET',  // [
    39→  RBRACKET = 'RBRACKET',  // ]
    40→  COLON = 'COLON',        // :
    41→  COMMA = 'COMMA',        // ,
    42→  ARROW = 'ARROW',        // ->
    43→  DOT = 'DOT',            // .
    44→
    45→  // 특수
    46→  INDENT = 'INDENT',
    47→  DEDENT = 'DEDENT',
    48→  NEWLINE = 'NEWLINE',
    49→  EOF = 'EOF',
    50→  COMMENT = 'COMMENT',
    51→}
    52→
    53→export interface V3Token {
    54→  type: V3TokenType;
    55→  value: any;
    56→  line: number;
    57→  column: number;
    58→  raw: string;
    59→}
    60→
    61→const V3_KEYWORDS = new Set([
    62→  // 타입
    63→  'ARR', 'INT', 'STR', 'BOOL', 'FLOAT',
    64→
    65→  // 배열 연산
    66→  'ARR_SUM', 'ARR_AVG', 'ARR_MAX', 'ARR_MIN', 'ARR_LEN',
    67→  'ARR_PUSH', 'ARR_GET', 'ARR_SET', 'ARR_MAP', 'ARR_FILTER',
    68→
    69→  // 제어흐름
    70→  'IF', 'ELSE', 'FOR', 'IN', 'WHILE', 'BREAK', 'CONTINUE',
    71→
    72→  // 함수
    73→  'FUNC', 'RETURN', 'CALL',
    74→
    75→  // 기타
    76→  'TRUE', 'FALSE', 'NONE', 'PRINTLN', 'INPUT',
    77→]);
    78→
    79→export class V3Lexer {
    80→  private source: string;
    81→  private pos: number = 0;
    82→  private line: number = 1;
    83→  private column: number = 1;
    84→  private tokens: V3Token[] = [];
    85→  private indentStack: number[] = [0];
    86→  private pendingDedents: number = 0;
    87→  private lineStart: boolean = true;
    88→
    89→  constructor(source: string) {
    90→    this.source = source;
    91→  }
    92→
    93→  tokenize(): V3Token[] {
    94→    while (this.pos < this.source.length) {
    95→      this.skipWhitespaceOnLine();
    96→
    97→      if (this.isNewline()) {
    98→        this.consumeNewline();
    99→        this.lineStart = true;
   100→        continue;
   101→      }
   102→
   103→      if (this.isComment()) {
   104→        this.skipComment();
   105→        continue;
   106→      }
   107→
   108→      // 줄 시작: 들여쓰기 처리
   109→      if (this.lineStart && !this.isNewline()) {
   110→        this.handleIndentation();
   111→        this.lineStart = false;
   112→      }
   113→
   114→      if (this.pos >= this.source.length) break;
   115→
   116→      const ch = this.peek();
   117→
   118→      // 문자열
   119→      if (ch === '"' || ch === "'") {
   120→        this.consumeString();
   121→        continue;
   122→      }
   123→
   124→      // 숫자
   125→      if (this.isDigit(ch)) {
   126→        this.consumeNumber();
   127→        continue;
   128→      }
   129→
   130→      // 식별자 또는 키워드
   131→      if (this.isLetter(ch) || ch === '_') {
   132→        this.consumeIdentifierOrKeyword();
   133→        continue;
   134→      }
   135→
   136→      // 연산자 및 기호
   137→      if (!this.consumeOperatorOrSymbol()) {
   138→        throw new Error(`미인식 문자 '${ch}' at line ${this.line}, column ${this.column}`);
   139→      }
   140→    }
   141→
   142→    // 파일 끝: DEDENT 생성
   143→    while (this.indentStack.length > 1) {
   144→      this.indentStack.pop();
   145→      this.addToken(V3TokenType.DEDENT, null);
   146→    }
   147→
   148→    this.addToken(V3TokenType.EOF, null);
   149→    return this.tokens;
   150→  }
   151→
   152→  private handleIndentation(): void {
   153→    let spaces = 0;
   154→    while (this.pos < this.source.length && this.peek() === ' ') {
   155→      spaces++;
   156→      this.pos++;
   157→      this.column++;
   158→    }
   159→
   160→    const currentIndent = this.indentStack[this.indentStack.length - 1];
   161→
   162→    if (spaces > currentIndent) {
   163→      this.indentStack.push(spaces);
   164→      this.addToken(V3TokenType.INDENT, null);
   165→    } else if (spaces < currentIndent) {
   166→      while (this.indentStack.length > 1 && this.indentStack[this.indentStack.length - 1] > spaces) {
   167→        this.indentStack.pop();
   168→        this.addToken(V3TokenType.DEDENT, null);
   169→      }
   170→    }
   171→  }
   172→
   173→  private consumeString(): void {
   174→    const quote = this.peek();
   175→    const startLine = this.line;
   176→    const startCol = this.column;
   177→    this.pos++;
   178→    this.column++;
   179→
   180→    let value = '';
   181→    while (this.pos < this.source.length && this.peek() !== quote) {
   182→      if (this.peek() === '\\' && this.peekNext() === quote) {
   183→        this.pos += 2;
   184→        this.column += 2;
   185→        value += quote;
   186→      } else if (this.peek() === '\\' && this.peekNext() === 'n') {
   187→        this.pos += 2;
   188→        this.column += 2;
   189→        value += '\n';
   190→      } else {
   191→        value += this.peek();
   192→        this.pos++;
   193→        this.column++;
   194→      }
   195→    }
   196→
   197→    if (this.pos >= this.source.length) {
   198→      throw new Error(`닫히지 않은 문자열 at line ${startLine}, column ${startCol}`);
   199→    }
   200→
   201→    this.pos++;
   202→    this.column++;
   203→    this.addToken(V3TokenType.STRING, value);
   204→  }
   205→
   206→  private consumeNumber(): void {
   207→    let value = '';
   208→    while (this.pos < this.source.length && this.isDigit(this.peek())) {
   209→      value += this.peek();
   210→      this.pos++;
   211→      this.column++;
   212→    }
   213→
   214→    if (this.peek() === '.' && this.isDigit(this.peekNext())) {
   215→      value += '.';
   216→      this.pos++;
   217→      this.column++;
   218→      while (this.pos < this.source.length && this.isDigit(this.peek())) {
   219→        value += this.peek();
   220→        this.pos++;
   221→        this.column++;
   222→      }
   223→    }
   224→
   225→    this.addToken(V3TokenType.NUMBER, parseFloat(value));
   226→  }
   227→
   228→  private consumeIdentifierOrKeyword(): void {
   229→    let value = '';
   230→    while (
   231→      this.pos < this.source.length &&
   232→      (this.isLetter(this.peek()) || this.isDigit(this.peek()) || this.peek() === '_')
   233→    ) {
   234→      value += this.peek();
   235→      this.pos++;
   236→      this.column++;
   237→    }
   238→
   239→    if (V3_KEYWORDS.has(value)) {
   240→      if (value === 'TRUE') {
   241→        this.addToken(V3TokenType.BOOL, true);
   242→      } else if (value === 'FALSE') {
   243→        this.addToken(V3TokenType.BOOL, false);
   244→      } else {
   245→        this.addToken(V3TokenType.KEYWORD, value);
   246→      }
   247→    } else {
   248→      this.addToken(V3TokenType.IDENTIFIER, value);
   249→    }
   250→  }
   251→
   252→  private consumeOperatorOrSymbol(): boolean {
   253→    const ch = this.peek();
   254→    const next = this.peekNext();
   255→
   256→    // 2글자 연산자
   257→    if (ch === '-' && next === '>') {
   258→      this.pos += 2;
   259→      this.column += 2;
   260→      this.addToken(V3TokenType.ARROW, '->');
   261→      return true;
   262→    }
   263→
   264→    if (ch === '=' && next === '=') {
   265→      this.pos += 2;
   266→      this.column += 2;
   267→      this.addToken(V3TokenType.EQ, '==');
   268→      return true;
   269→    }
   270→
   271→    if (ch === '!' && next === '=') {
   272→      this.pos += 2;
   273→      this.column += 2;
   274→      this.addToken(V3TokenType.NE, '!=');
   275→      return true;
   276→    }
   277→
   278→    if (ch === '<' && next === '=') {
   279→      this.pos += 2;
   280→      this.column += 2;
   281→      this.addToken(V3TokenType.LE, '<=');
   282→      return true;
   283→    }
   284→
   285→    if (ch === '>' && next === '=') {
   286→      this.pos += 2;
   287→      this.column += 2;
   288→      this.addToken(V3TokenType.GE, '>=');
   289→      return true;
   290→    }
   291→
   292→    // 1글자 연산자
   293→    const singleCharTokens: { [key: string]: V3TokenType } = {
   294→      '+': V3TokenType.PLUS,
   295→      '-': V3TokenType.MINUS,
   296→      '*': V3TokenType.STAR,
   297→      '/': V3TokenType.SLASH,
   298→      '=': V3TokenType.ASSIGN,
   299→      '<': V3TokenType.LT,
   300→      '>': V3TokenType.GT,
   301→      '(': V3TokenType.LPAREN,
   302→      ')': V3TokenType.RPAREN,
   303→      '[': V3TokenType.LBRACKET,
   304→      ']': V3TokenType.RBRACKET,
   305→      ':': V3TokenType.COLON,
   306→      ',': V3TokenType.COMMA,
   307→      '.': V3TokenType.DOT,
   308→    };
   309→
   310→    if (singleCharTokens[ch]) {
   311→      this.addToken(singleCharTokens[ch], ch);
   312→      this.pos++;
   313→      this.column++;
   314→      return true;
   315→    }
   316→
   317→    return false;
   318→  }
   319→
   320→  private skipWhitespaceOnLine(): void {
   321→    while (this.pos < this.source.length && this.peek() === ' ') {
   322→      this.pos++;
   323→      this.column++;
   324→    }
   325→  }
   326→
   327→  private skipComment(): void {
   328→    if (this.peek() === '#') {
   329→      while (this.pos < this.source.length && !this.isNewline()) {
   330→        this.pos++;
   331→        this.column++;
   332→      }
   333→    }
   334→  }
   335→
   336→  private consumeNewline(): void {
   337→    if (this.peek() === '\r' && this.peekNext() === '\n') {
   338→      this.pos += 2;
   339→    } else {
   340→      this.pos++;
   341→    }
   342→    this.line++;
   343→    this.column = 1;
   344→    this.addToken(V3TokenType.NEWLINE, '\n');
   345→  }
   346→
   347→  private isNewline(): boolean {
   348→    return this.peek() === '\n' || (this.peek() === '\r' && this.peekNext() === '\n');
   349→  }
   350→
   351→  private isComment(): boolean {
   352→    return this.peek() === '#';
   353→  }
   354→
   355→  private isDigit(ch: string): boolean {
   356→    return ch >= '0' && ch <= '9';
   357→  }
   358→
   359→  private isLetter(ch: string): boolean {
   360→    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
   361→  }
   362→
   363→  private peek(): string {
   364→    return this.pos < this.source.length ? this.source[this.pos] : '\0';
   365→  }
   366→
   367→  private peekNext(): string {
   368→    return this.pos + 1 < this.source.length ? this.source[this.pos + 1] : '\0';
   369→  }
   370→
   371→  private addToken(type: V3TokenType, value: any): void {
   372→    this.tokens.push({
   373→      type,
   374→      value,
   375→      line: this.line,
   376→      column: this.column,
   377→      raw: value?.toString() || '',
   378→    });
   379→  }
   380→}
