     1→/**
     2→ * V3 Parser (구문 분석기)
     3→ *
     4→ * 토큰 → AST (Abstract Syntax Tree) 변환
     5→ */
     6→
     7→import { V3Token, V3TokenType, V3Lexer } from './v3-lexer';
     8→
     9→export interface V3ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→}
    14→
    15→export interface V3Program extends V3ASTNode {
    16→  type: 'Program';
    17→  statements: V3Statement[];
    18→}
    19→
    20→export type V3Statement = V3VarDecl | V3IfStmt | V3ForLoop | V3FuncDecl | V3ExprStmt | V3ReturnStmt;
    21→
    22→export interface V3VarDecl extends V3ASTNode {
    23→  type: 'VarDecl';
    24→  varType: 'ARR' | 'INT' | 'STR' | 'BOOL' | 'FLOAT';
    25→  name: string;
    26→  value: V3Expr;
    27→}
    28→
    29→export interface V3IfStmt extends V3ASTNode {
    30→  type: 'IfStmt';
    31→  condition: V3Expr;
    32→  thenBlock: V3Statement[];
    33→  elseBlock?: V3Statement[];
    34→}
    35→
    36→export interface V3ForLoop extends V3ASTNode {
    37→  type: 'ForLoop';
    38→  variable: string;
    39→  iterable: V3Expr;
    40→  body: V3Statement[];
    41→}
    42→
    43→export interface V3FuncDecl extends V3ASTNode {
    44→  type: 'FuncDecl';
    45→  name: string;
    46→  params: Array<{ name: string; type: string }>;
    47→  returnType: string;
    48→  body: V3Statement[];
    49→}
    50→
    51→export interface V3ExprStmt extends V3ASTNode {
    52→  type: 'ExprStmt';
    53→  expr: V3Expr;
    54→}
    55→
    56→export interface V3ReturnStmt extends V3ASTNode {
    57→  type: 'ReturnStmt';
    58→  value?: V3Expr;
    59→}
    60→
    61→export type V3Expr =
    62→  | V3Number
    63→  | V3String
    64→  | V3Bool
    65→  | V3Identifier
    66→  | V3BinaryOp
    67→  | V3UnaryOp
    68→  | V3ArrayLiteral
    69→  | V3ArrayAccess
    70→  | V3ArrayOp
    71→  | V3FuncCall
    72→  | V3Assignment;
    73→
    74→export interface V3Number extends V3ASTNode {
    75→  type: 'Number';
    76→  value: number;
    77→}
    78→
    79→export interface V3String extends V3ASTNode {
    80→  type: 'String';
    81→  value: string;
    82→}
    83→
    84→export interface V3Bool extends V3ASTNode {
    85→  type: 'Bool';
    86→  value: boolean;
    87→}
    88→
    89→export interface V3Identifier extends V3ASTNode {
    90→  type: 'Identifier';
    91→  name: string;
    92→}
    93→
    94→export interface V3BinaryOp extends V3ASTNode {
    95→  type: 'BinaryOp';
    96→  left: V3Expr;
    97→  op: string;
    98→  right: V3Expr;
    99→}
   100→
   101→export interface V3UnaryOp extends V3ASTNode {
   102→  type: 'UnaryOp';
   103→  op: string;
   104→  operand: V3Expr;
   105→}
   106→
   107→export interface V3ArrayLiteral extends V3ASTNode {
   108→  type: 'ArrayLiteral';
   109→  elements: V3Expr[];
   110→}
   111→
   112→export interface V3ArrayAccess extends V3ASTNode {
   113→  type: 'ArrayAccess';
   114→  array: V3Expr;
   115→  index: V3Expr;
   116→}
   117→
   118→export interface V3ArrayOp extends V3ASTNode {
   119→  type: 'ArrayOp';
   120→  op: 'ARR_SUM' | 'ARR_AVG' | 'ARR_MAX' | 'ARR_MIN' | 'ARR_LEN' | 'ARR_MAP' | 'ARR_FILTER';
   121→  array: V3Expr;
   122→  callback?: V3Expr;
   123→}
   124→
   125→export interface V3FuncCall extends V3ASTNode {
   126→  type: 'FuncCall';
   127→  name: string;
   128→  args: V3Expr[];
   129→}
   130→
   131→export interface V3Assignment extends V3ASTNode {
   132→  type: 'Assignment';
   133→  name: string;
   134→  value: V3Expr;
   135→}
   136→
   137→export class V3Parser {
   138→  private tokens: V3Token[];
   139→  private pos: number = 0;
   140→
   141→  constructor(source: string) {
   142→    const lexer = new V3Lexer(source);
   143→    this.tokens = lexer.tokenize();
   144→  }
   145→
   146→  parse(): V3Program {
   147→    const statements: V3Statement[] = [];
   148→
   149→    while (!this.isAtEnd()) {
   150→      if (this.check(V3TokenType.NEWLINE)) {
   151→        this.advance();
   152→        continue;
   153→      }
   154→      statements.push(this.parseStatement());
   155→    }
   156→
   157→    return {
   158→      type: 'Program',
   159→      statements,
   160→      line: 1,
   161→      column: 1,
   162→    };
   163→  }
   164→
   165→  private parseStatement(): V3Statement {
   166→    const token = this.peek();
   167→
   168→    // 변수 선언
   169→    if (this.isType(token)) {
   170→      return this.parseVarDecl();
   171→    }
   172→
   173→    // IF 문
   174→    if (this.match(V3TokenType.KEYWORD, 'IF')) {
   175→      return this.parseIfStmt();
   176→    }
   177→
   178→    // FOR 루프
   179→    if (this.match(V3TokenType.KEYWORD, 'FOR')) {
   180→      return this.parseForLoop();
   181→    }
   182→
   183→    // 함수 선언
   184→    if (this.match(V3TokenType.KEYWORD, 'FUNC')) {
   185→      return this.parseFuncDecl();
   186→    }
   187→
   188→    // RETURN
   189→    if (this.match(V3TokenType.KEYWORD, 'RETURN')) {
   190→      const returnStmt: V3ReturnStmt = {
   191→        type: 'ReturnStmt',
   192→        value: this.check(V3TokenType.NEWLINE) ? undefined : this.parseExpr(),
   193→        line: token.line,
   194→        column: token.column,
   195→      };
   196→      this.consumeNewline();
   197→      return returnStmt;
   198→    }
   199→
   200→    // 표현식 문
   201→    const expr = this.parseExpr();
   202→    this.consumeNewline();
   203→    return {
   204→      type: 'ExprStmt',
   205→      expr,
   206→      line: token.line,
   207→      column: token.column,
   208→    };
   209→  }
   210→
   211→  private parseVarDecl(): V3VarDecl {
   212→    const token = this.peek();
   213→    const varType = this.advance().value;
   214→    const name = this.consume(V3TokenType.IDENTIFIER, '변수명 필요').value;
   215→    this.consume(V3TokenType.ASSIGN, '= 필요');
   216→    const value = this.parseExpr();
   217→    this.consumeNewline();
   218→
   219→    return {
   220→      type: 'VarDecl',
   221→      varType,
   222→      name,
   223→      value,
   224→      line: token.line,
   225→      column: token.column,
   226→    };
   227→  }
   228→
   229→  private parseIfStmt(): V3IfStmt {
   230→    const token = this.peek();
   231→    const condition = this.parseExpr();
   232→    this.consume(V3TokenType.COLON, ': 필요');
   233→    this.consumeNewline();
   234→
   235→    const thenBlock = this.parseBlock();
   236→
   237→    let elseBlock: V3Statement[] | undefined;
   238→    if (this.check(V3TokenType.KEYWORD) && this.peekValue() === 'ELSE') {
   239→      this.advance();
   240→      this.consume(V3TokenType.COLON, ': 필요');
   241→      this.consumeNewline();
   242→      elseBlock = this.parseBlock();
   243→    }
   244→
   245→    return {
   246→      type: 'IfStmt',
   247→      condition,
   248→      thenBlock,
   249→      elseBlock,
   250→      line: token.line,
   251→      column: token.column,
   252→    };
   253→  }
   254→
   255→  private parseForLoop(): V3ForLoop {
   256→    const token = this.peek();
   257→    const variable = this.consume(V3TokenType.IDENTIFIER, '변수명 필요').value;
   258→    this.consume(V3TokenType.KEYWORD, 'IN 필요', 'IN');
   259→    const iterable = this.parseExpr();
   260→    this.consume(V3TokenType.COLON, ': 필요');
   261→    this.consumeNewline();
   262→
   263→    const body = this.parseBlock();
   264→
   265→    return {
   266→      type: 'ForLoop',
   267→      variable,
   268→      iterable,
   269→      body,
   270→      line: token.line,
   271→      column: token.column,
   272→    };
   273→  }
   274→
   275→  private parseFuncDecl(): V3FuncDecl {
   276→    const token = this.peek();
   277→    const name = this.consume(V3TokenType.IDENTIFIER, '함수명 필요').value;
   278→    this.consume(V3TokenType.LPAREN, '( 필요');
   279→
   280→    const params: Array<{ name: string; type: string }> = [];
   281→    while (!this.check(V3TokenType.RPAREN)) {
   282→      const paramName = this.consume(V3TokenType.IDENTIFIER, '파라미터명 필요').value;
   283→      this.consume(V3TokenType.COLON, ': 필요');
   284→      const paramType = this.consume(V3TokenType.KEYWORD, '타입 필요').value;
   285→      params.push({ name: paramName, type: paramType });
   286→
   287→      if (!this.check(V3TokenType.RPAREN)) {
   288→        this.consume(V3TokenType.COMMA, ', 필요');
   289→      }
   290→    }
   291→    this.consume(V3TokenType.RPAREN, ') 필요');
   292→
   293→    this.consume(V3TokenType.ARROW, '-> 필요');
   294→    const returnType = this.consume(V3TokenType.KEYWORD, '반환 타입 필요').value;
   295→    this.consume(V3TokenType.COLON, ': 필요');
   296→    this.consumeNewline();
   297→
   298→    const body = this.parseBlock();
   299→
   300→    return {
   301→      type: 'FuncDecl',
   302→      name,
   303→      params,
   304→      returnType,
   305→      body,
   306→      line: token.line,
   307→      column: token.column,
   308→    };
   309→  }
   310→
   311→  private parseBlock(): V3Statement[] {
   312→    const statements: V3Statement[] = [];
   313→
   314→    this.consume(V3TokenType.INDENT, 'INDENT 필요');
   315→
   316→    while (!this.check(V3TokenType.DEDENT) && !this.isAtEnd()) {
   317→      if (this.check(V3TokenType.NEWLINE)) {
   318→        this.advance();
   319→        continue;
   320→      }
   321→      statements.push(this.parseStatement());
   322→    }
   323→
   324→    this.consume(V3TokenType.DEDENT, 'DEDENT 필요');
   325→
   326→    return statements;
   327→  }
   328→
   329→  private parseExpr(): V3Expr {
   330→    return this.parseAssignmentOrExpr();
   331→  }
   332→
   333→  private parseAssignmentOrExpr(): V3Expr {
   334→    let expr = this.parseOr();
   335→
   336→    if (this.check(V3TokenType.IDENTIFIER) && this.peekAhead(1)?.type === V3TokenType.ASSIGN) {
   337→      const name = this.advance().value;
   338→      this.advance(); // =
   339→      const value = this.parseExpr();
   340→      return {
   341→        type: 'Assignment',
   342→        name,
   343→        value,
   344→        line: expr.line,
   345→        column: expr.column,
   346→      };
   347→    }
   348→
   349→    return expr;
   350→  }
   351→
   352→  private parseOr(): V3Expr {
   353→    let expr = this.parseAnd();
   354→
   355→    while (this.match(V3TokenType.KEYWORD, 'OR')) {
   356→      const op = this.previous().value;
   357→      const right = this.parseAnd();
   358→      expr = {
   359→        type: 'BinaryOp',
   360→        left: expr,
   361→        op,
   362→        right,
   363→        line: expr.line,
   364→        column: expr.column,
   365→      };
   366→    }
   367→
   368→    return expr;
   369→  }
   370→
   371→  private parseAnd(): V3Expr {
   372→    let expr = this.parseComparison();
   373→
   374→    while (this.match(V3TokenType.KEYWORD, 'AND')) {
   375→      const op = this.previous().value;
   376→      const right = this.parseComparison();
   377→      expr = {
   378→        type: 'BinaryOp',
   379→        left: expr,
   380→        op,
   381→        right,
   382→        line: expr.line,
   383→        column: expr.column,
   384→      };
   385→    }
   386→
   387→    return expr;
   388→  }
   389→
   390→  private parseComparison(): V3Expr {
   391→    let expr = this.parseAdditive();
   392→
   393→    while (
   394→      this.match(V3TokenType.EQ) ||
   395→      this.match(V3TokenType.NE) ||
   396→      this.match(V3TokenType.LT) ||
   397→      this.match(V3TokenType.LE) ||
   398→      this.match(V3TokenType.GT) ||
   399→      this.match(V3TokenType.GE)
   400→    ) {
   401→      const op = this.previous().raw;
   402→      const right = this.parseAdditive();
   403→      expr = {
   404→        type: 'BinaryOp',
   405→        left: expr,
   406→        op,
   407→        right,
   408→        line: expr.line,
   409→        column: expr.column,
   410→      };
   411→    }
   412→
   413→    return expr;
   414→  }
   415→
   416→  private parseAdditive(): V3Expr {
   417→    let expr = this.parseMultiplicative();
   418→
   419→    while (this.match(V3TokenType.PLUS) || this.match(V3TokenType.MINUS)) {
   420→      const op = this.previous().raw;
   421→      const right = this.parseMultiplicative();
   422→      expr = {
   423→        type: 'BinaryOp',
   424→        left: expr,
   425→        op,
   426→        right,
   427→        line: expr.line,
   428→        column: expr.column,
   429→      };
   430→    }
   431→
   432→    return expr;
   433→  }
   434→
   435→  private parseMultiplicative(): V3Expr {
   436→    let expr = this.parseUnary();
   437→
   438→    while (this.match(V3TokenType.STAR) || this.match(V3TokenType.SLASH)) {
   439→      const op = this.previous().raw;
   440→      const right = this.parseUnary();
   441→      expr = {
   442→        type: 'BinaryOp',
   443→        left: expr,
   444→        op,
   445→        right,
   446→        line: expr.line,
   447→        column: expr.column,
   448→      };
   449→    }
   450→
   451→    return expr;
   452→  }
   453→
   454→  private parseUnary(): V3Expr {
   455→    if (this.match(V3TokenType.MINUS)) {
   456→      const op = this.previous().raw;
   457→      const expr = this.parseUnary();
   458→      return {
   459→        type: 'UnaryOp',
   460→        op,
   461→        operand: expr,
   462→        line: expr.line,
   463→        column: expr.column,
   464→      };
   465→    }
   466→
   467→    return this.parsePostfix();
   468→  }
   469→
   470→  private parsePostfix(): V3Expr {
   471→    let expr = this.parsePrimary();
   472→
   473→    while (true) {
   474→      if (this.match(V3TokenType.LBRACKET)) {
   475→        const index = this.parseExpr();
   476→        this.consume(V3TokenType.RBRACKET, '] 필요');
   477→        expr = {
   478→          type: 'ArrayAccess',
   479→          array: expr,
   480→          index,
   481→          line: expr.line,
   482→          column: expr.column,
   483→        };
   484→      } else if (this.match(V3TokenType.LPAREN) && expr.type === 'Identifier') {
   485→        const args: V3Expr[] = [];
   486→        while (!this.check(V3TokenType.RPAREN)) {
   487→          args.push(this.parseExpr());
   488→          if (!this.check(V3TokenType.RPAREN)) {
   489→            this.consume(V3TokenType.COMMA, ', 필요');
   490→          }
   491→        }
   492→        this.consume(V3TokenType.RPAREN, ') 필요');
   493→        expr = {
   494→          type: 'FuncCall',
   495→          name: (expr as V3Identifier).name,
   496→          args,
   497→          line: expr.line,
   498→          column: expr.column,
   499→        };
   500→      } else {
   501→        break;
   502→      }
   503→    }
   504→
   505→    return expr;
   506→  }
   507→
   508→  private parsePrimary(): V3Expr {
   509→    const token = this.peek();
   510→
   511→    // 숫자
   512→    if (this.match(V3TokenType.NUMBER)) {
   513→      return {
   514→        type: 'Number',
   515→        value: this.previous().value,
   516→        line: token.line,
   517→        column: token.column,
   518→      };
   519→    }
   520→
   521→    // 문자열
   522→    if (this.match(V3TokenType.STRING)) {
   523→      return {
   524→        type: 'String',
   525→        value: this.previous().value,
   526→        line: token.line,
   527→        column: token.column,
   528→      };
   529→    }
   530→
   531→    // 불린
   532→    if (this.match(V3TokenType.BOOL)) {
   533→      return {
   534→        type: 'Bool',
   535→        value: this.previous().value,
   536→        line: token.line,
   537→        column: token.column,
   538→      };
   539→    }
   540→
   541→    // 배열 리터럴
   542→    if (this.match(V3TokenType.LBRACKET)) {
   543→      const elements: V3Expr[] = [];
   544→      while (!this.check(V3TokenType.RBRACKET)) {
   545→        elements.push(this.parseExpr());
   546→        if (!this.check(V3TokenType.RBRACKET)) {
   547→          this.consume(V3TokenType.COMMA, ', 필요');
   548→        }
   549→      }
   550→      this.consume(V3TokenType.RBRACKET, '] 필요');
   551→      return {
   552→        type: 'ArrayLiteral',
   553→        elements,
   554→        line: token.line,
   555→        column: token.column,
   556→      };
   557→    }
   558→
   559→    // 배열 연산 (ARR_SUM 등)
   560→    if (this.checkKeyword('ARR_SUM') || this.checkKeyword('ARR_AVG') || this.checkKeyword('ARR_MAX') || this.checkKeyword('ARR_MIN')) {
   561→      const op = this.advance().value;
   562→      const array = this.parsePostfix();
   563→      return {
   564→        type: 'ArrayOp',
   565→        op,
   566→        array,
   567→        line: token.line,
   568→        column: token.column,
   569→      };
   570→    }
   571→
   572→    // 괄호 표현식
   573→    if (this.match(V3TokenType.LPAREN)) {
   574→      const expr = this.parseExpr();
   575→      this.consume(V3TokenType.RPAREN, ') 필요');
   576→      return expr;
   577→    }
   578→
   579→    // 식별자
   580→    if (this.match(V3TokenType.IDENTIFIER)) {
   581→      return {
   582→        type: 'Identifier',
   583→        name: this.previous().value,
   584→        line: token.line,
   585→        column: token.column,
   586→      };
   587→    }
   588→
   589→    throw new Error(`예상치 못한 토큰: ${token.type} at line ${token.line}`);
   590→  }
   591→
   592→  private isType(token: V3Token): boolean {
   593→    if (token.type !== V3TokenType.KEYWORD) return false;
   594→    return ['ARR', 'INT', 'STR', 'BOOL', 'FLOAT'].includes(token.value);
   595→  }
   596→
   597→  private checkKeyword(keyword: string): boolean {
   598→    return this.check(V3TokenType.KEYWORD) && this.peekValue() === keyword;
   599→  }
   600→
   601→  private match(...args: any[]): boolean {
   602→    for (const arg of args) {
   603→      if (typeof arg === 'string') {
   604→        if (this.check(V3TokenType.KEYWORD) && this.peekValue() === arg) {
   605→          this.advance();
   606→          return true;
   607→        }
   608→      } else if (this.check(arg)) {
   609→        this.advance();
   610→        return true;
   611→      }
   612→    }
   613→    return false;
   614→  }
   615→
   616→  private check(type: V3TokenType): boolean {
   617→    if (this.isAtEnd()) return false;
   618→    return this.peek().type === type;
   619→  }
   620→
   621→  private advance(): V3Token {
   622→    if (!this.isAtEnd()) this.pos++;
   623→    return this.previous();
   624→  }
   625→
   626→  private isAtEnd(): boolean {
   627→    return this.peek().type === V3TokenType.EOF;
   628→  }
   629→
   630→  private peek(): V3Token {
   631→    return this.tokens[this.pos];
   632→  }
   633→
   634→  private peekValue(): any {
   635→    return this.peek().value;
   636→  }
   637→
   638→  private peekAhead(n: number): V3Token | undefined {
   639→    return this.tokens[this.pos + n];
   640→  }
   641→
   642→  private previous(): V3Token {
   643→    return this.tokens[this.pos - 1];
   644→  }
   645→
   646→  private consume(type: V3TokenType, message: string, value?: string): V3Token {
   647→    if (this.check(type)) {
   648→      if (value && this.peekValue() !== value) {
   649→        throw new Error(`${message} (기대값: ${value}, 실제: ${this.peekValue()})`);
   650→      }
   651→      return this.advance();
   652→    }
   653→
   654→    const token = this.peek();
   655→    throw new Error(`${message} at line ${token.line}`);
   656→  }
   657→
   658→  private consumeNewline(): void {
   659→    while (this.check(V3TokenType.NEWLINE)) {
   660→      this.advance();
   661→    }
   662→  }
   663→}
