     1→/**
     2→ * V3 Executor (V3 언어 실행 엔진)
     3→ *
     4→ * AST를 직접 해석하여 실행 (Interpreter 방식)
     5→ * - 더 간단하고 명확함
     6→ * - 디버깅 가능
     7→ * - 동작 보장
     8→ */
     9→
    10→import { V3Program, V3Statement, V3Expr } from './v3-parser';
    11→
    12→export interface V3Value {
    13→  type: 'number' | 'string' | 'boolean' | 'array' | 'function' | 'null';
    14→  value: any;
    15→}
    16→
    17→export class V3Executor {
    18→  private globals: Map<string, V3Value> = new Map();
    19→  private locals: Map<string, V3Value>[] = [new Map()];
    20→  private output: string[] = [];
    21→  private returnValue: V3Value | null = null;
    22→  private shouldReturn: boolean = false;
    23→  private functions: Map<string, V3FunctionDef> = new Map();
    24→
    25→  interface V3FunctionDef {
    26→    params: Array<{ name: string; type: string }>;
    27→    body: V3Statement[];
    28→  }
    29→
    30→  constructor() {
    31→    // 빌트인 함수들
    32→    this.registerBuiltins();
    33→  }
    34→
    35→  private registerBuiltins(): void {
    36→    // println은 특수 처리
    37→    // input도 특수 처리
    38→  }
    39→
    40→  execute(program: V3Program): { output: string; success: boolean; error?: string } {
    41→    try {
    42→      for (const stmt of program.statements) {
    43→        this.executeStatement(stmt);
    44→        if (this.shouldReturn) break;
    45→      }
    46→
    47→      return {
    48→        output: this.output.join('\n'),
    49→        success: true,
    50→      };
    51→    } catch (error) {
    52→      return {
    53→        output: this.output.join('\n'),
    54→        success: false,
    55→        error: (error as any).message,
    56→      };
    57→    }
    58→  }
    59→
    60→  private executeStatement(stmt: V3Statement): void {
    61→    switch (stmt.type) {
    62→      case 'VarDecl': {
    63→        const varDecl = stmt as any;
    64→        const value = this.evaluateExpr(varDecl.value);
    65→        this.setVariable(varDecl.name, value);
    66→        break;
    67→      }
    68→
    69→      case 'IfStmt': {
    70→        const ifStmt = stmt as any;
    71→        const condition = this.evaluateExpr(ifStmt.condition);
    72→        if (this.isTruthy(condition)) {
    73→          for (const s of ifStmt.thenBlock) {
    74→            this.executeStatement(s);
    75→            if (this.shouldReturn) return;
    76→          }
    77→        } else if (ifStmt.elseBlock) {
    78→          for (const s of ifStmt.elseBlock) {
    79→            this.executeStatement(s);
    80→            if (this.shouldReturn) return;
    81→          }
    82→        }
    83→        break;
    84→      }
    85→
    86→      case 'ForLoop': {
    87→        const forLoop = stmt as any;
    88→        const iterable = this.evaluateExpr(forLoop.iterable);
    89→
    90→        if (iterable.type !== 'array') {
    91→          throw new Error('FOR IN은 배열에만 사용 가능');
    92→        }
    93→
    94→        for (const item of iterable.value) {
    95→          this.setVariable(forLoop.variable, item);
    96→          for (const s of forLoop.body) {
    97→            this.executeStatement(s);
    98→            if (this.shouldReturn) return;
    99→          }
   100→        }
   101→        break;
   102→      }
   103→
   104→      case 'FuncDecl': {
   105→        const funcDecl = stmt as any;
   106→        this.functions.set(funcDecl.name, {
   107→          params: funcDecl.params,
   108→          body: funcDecl.body,
   109→        });
   110→        break;
   111→      }
   112→
   113→      case 'ReturnStmt': {
   114→        const returnStmt = stmt as any;
   115→        if (returnStmt.value) {
   116→          this.returnValue = this.evaluateExpr(returnStmt.value);
   117→        } else {
   118→          this.returnValue = { type: 'null', value: null };
   119→        }
   120→        this.shouldReturn = true;
   121→        break;
   122→      }
   123→
   124→      case 'ExprStmt': {
   125→        const exprStmt = stmt as any;
   126→        this.evaluateExpr(exprStmt.expr);
   127→        break;
   128→      }
   129→    }
   130→  }
   131→
   132→  private evaluateExpr(expr: V3Expr): V3Value {
   133→    switch (expr.type) {
   134→      case 'Number': {
   135→        const numExpr = expr as any;
   136→        return { type: 'number', value: numExpr.value };
   137→      }
   138→
   139→      case 'String': {
   140→        const strExpr = expr as any;
   141→        return { type: 'string', value: strExpr.value };
   142→      }
   143→
   144→      case 'Bool': {
   145→        const boolExpr = expr as any;
   146→        return { type: 'boolean', value: boolExpr.value };
   147→      }
   148→
   149→      case 'Identifier': {
   150→        const idExpr = expr as any;
   151→        return this.getVariable(idExpr.name);
   152→      }
   153→
   154→      case 'ArrayLiteral': {
   155→        const arrLit = expr as any;
   156→        const elements = arrLit.elements.map((e: V3Expr) => this.evaluateExpr(e));
   157→        return { type: 'array', value: elements };
   158→      }
   159→
   160→      case 'BinaryOp': {
   161→        const binOp = expr as any;
   162→        const left = this.evaluateExpr(binOp.left);
   163→        const right = this.evaluateExpr(binOp.right);
   164→
   165→        switch (binOp.op) {
   166→          case '+':
   167→            if (left.type === 'number' && right.type === 'number') {
   168→              return { type: 'number', value: left.value + right.value };
   169→            }
   170→            if (left.type === 'string' || right.type === 'string') {
   171→              return { type: 'string', value: String(left.value) + String(right.value) };
   172→            }
   173→            throw new Error(`+ 연산 불가: ${left.type} + ${right.type}`);
   174→
   175→          case '-':
   176→            if (left.type === 'number' && right.type === 'number') {
   177→              return { type: 'number', value: left.value - right.value };
   178→            }
   179→            throw new Error(`- 연산 불가: ${left.type} - ${right.type}`);
   180→
   181→          case '*':
   182→            if (left.type === 'number' && right.type === 'number') {
   183→              return { type: 'number', value: left.value * right.value };
   184→            }
   185→            throw new Error(`* 연산 불가: ${left.type} * ${right.type}`);
   186→
   187→          case '/':
   188→            if (left.type === 'number' && right.type === 'number') {
   189→              if (right.value === 0) throw new Error('0으로 나눌 수 없음');
   190→              return { type: 'number', value: left.value / right.value };
   191→            }
   192→            throw new Error(`/ 연산 불가: ${left.type} / ${right.type}`);
   193→
   194→          case '==':
   195→            return { type: 'boolean', value: this.areEqual(left, right) };
   196→
   197→          case '!=':
   198→            return { type: 'boolean', value: !this.areEqual(left, right) };
   199→
   200→          case '<':
   201→            if (left.type === 'number' && right.type === 'number') {
   202→              return { type: 'boolean', value: left.value < right.value };
   203→            }
   204→            throw new Error(`< 연산 불가: ${left.type} < ${right.type}`);
   205→
   206→          case '<=':
   207→            if (left.type === 'number' && right.type === 'number') {
   208→              return { type: 'boolean', value: left.value <= right.value };
   209→            }
   210→            throw new Error(`<= 연산 불가: ${left.type} <= ${right.type}`);
   211→
   212→          case '>':
   213→            if (left.type === 'number' && right.type === 'number') {
   214→              return { type: 'boolean', value: left.value > right.value };
   215→            }
   216→            throw new Error(`> 연산 불가: ${left.type} > ${right.type}`);
   217→
   218→          case '>=':
   219→            if (left.type === 'number' && right.type === 'number') {
   220→              return { type: 'boolean', value: left.value >= right.value };
   221→            }
   222→            throw new Error(`>= 연산 불가: ${left.type} >= ${right.type}`);
   223→
   224→          case 'AND':
   225→            return { type: 'boolean', value: this.isTruthy(left) && this.isTruthy(right) };
   226→
   227→          case 'OR':
   228→            return { type: 'boolean', value: this.isTruthy(left) || this.isTruthy(right) };
   229→
   230→          default:
   231→            throw new Error(`미지원 연산: ${binOp.op}`);
   232→        }
   233→      }
   234→
   235→      case 'UnaryOp': {
   236→        const unaryOp = expr as any;
   237→        const operand = this.evaluateExpr(unaryOp.operand);
   238→
   239→        if (unaryOp.op === '-') {
   240→          if (operand.type === 'number') {
   241→            return { type: 'number', value: -operand.value };
   242→          }
   243→          throw new Error(`- 단항 연산 불가: ${operand.type}`);
   244→        }
   245→
   246→        throw new Error(`미지원 단항 연산: ${unaryOp.op}`);
   247→      }
   248→
   249→      case 'ArrayAccess': {
