   251→        const array = this.evaluateExpr(arrAccess.array);
   252→        const index = this.evaluateExpr(arrAccess.index);
   253→
   254→        if (array.type !== 'array') {
   255→          throw new Error('배열이 아님');
   256→        }
   257→        if (index.type !== 'number') {
   258→          throw new Error('인덱스는 숫자여야 함');
   259→        }
   260→
   261→        const idx = Math.floor(index.value);
   262→        if (idx < 0 || idx >= array.value.length) {
