   291→
   292→          case 'ARR_MAX':
   293→            return { type: 'number', value: nums.length > 0 ? Math.max(...nums) : 0 };
   294→
   295→          case 'ARR_MIN':
   296→            return { type: 'number', value: nums.length > 0 ? Math.min(...nums) : 0 };
   297→
   298→          default:
   299→            throw new Error(`미지원 배열 연산: ${arrOp.op}`);
   300→        }
   301→      }
   302→
   303→      case 'FuncCall': {
   304→        const funcCall = expr as any;
   305→
