   315→          return { type: 'string', value: '' };
   316→        }
   317→
   318→        // 사용자 정의 함수
   319→        const func = this.functions.get(funcCall.name);
   320→        if (!func) {
   321→          throw new Error(`미정의 함수: ${funcCall.name}`);
   322→        }
   323→
   324→        // 새 스코프 생성
   325→        this.locals.push(new Map());
   326→
   327→        // 파라미터 바인딩
   328→        const args = funcCall.args.map((arg: V3Expr) => this.evaluateExpr(arg));
   329→        for (let i = 0; i < func.params.length; i++) {
   330→          const param = func.params[i];
   331→          const arg = args[i] || { type: 'null', value: null };
   332→          this.setVariable(param.name, arg);
   333→        }
   334→
   335→        // 함수 본체 실행
   336→        this.returnValue = null;
   337→        this.shouldReturn = false;
   338→        for (const stmt of func.body) {
   339→          this.executeStatement(stmt);
   340→          if (this.shouldReturn) break;
   341→        }
   342→
   343→        const result = this.returnValue || { type: 'null', value: null };
   344→        this.returnValue = null;
   345→        this.shouldReturn = false;
   346→
   347→        // 스코프 복원
   348→        this.locals.pop();
   349→
   350→        return result;
   351→      }
   352→
   353→      case 'Assignment': {
   354→        const assign = expr as any;
   355→        const value = this.evaluateExpr(assign.value);
   356→        this.setVariable(assign.name, value);
   357→        return value;
   358→      }
   359→
   360→      default:
   361→        throw new Error(`미지원 표현식: ${(expr as any).type}`);
   362→    }
   363→  }
   364→
   365→  private isTruthy(value: V3Value): boolean {
   366→    switch (value.type) {
   367→      case 'null':
   368→        return false;
   369→      case 'boolean':
   370→        return value.value;
   371→      case 'number':
   372→        return value.value !== 0;
   373→      case 'string':
   374→        return value.value.length > 0;
   375→      case 'array':
   376→        return value.value.length > 0;
   377→      default:
   378→        return true;
   379→    }
   380→  }
   381→
   382→  private areEqual(a: V3Value, b: V3Value): boolean {
   383→    if (a.type !== b.type) return false;
   384→    return a.value === b.value;
   385→  }
   386→
   387→  private stringify(value: V3Value): string {
   388→    switch (value.type) {
   389→      case 'null':
   390→        return 'null';
   391→      case 'boolean':
   392→        return value.value ? 'true' : 'false';
   393→      case 'number':
   394→        return String(value.value);
   395→      case 'string':
   396→        return value.value;
   397→      case 'array':
   398→        return '[' + value.value.map((v: V3Value) => this.stringify(v)).join(', ') + ']';
   399→      case 'function':
   400→        return '<function>';
   401→      default:
   402→        return String(value);
   403→    }
   404→  }
   405→
   406→  private getVariable(name: string): V3Value {
   407→    // 지역 스코프에서 먼저 찾기
   408→    for (let i = this.locals.length - 1; i >= 0; i--) {
   409→      if (this.locals[i].has(name)) {
   410→        return this.locals[i].get(name)!;
   411→      }
   412→    }
   413→
   414→    // 전역 스코프에서 찾기
   415→    if (this.globals.has(name)) {
   416→      return this.globals.get(name)!;
   417→    }
   418→
   419→    throw new Error(`미정의 변수: ${name}`);
   420→  }
   421→
   422→  private setVariable(name: string, value: V3Value): void {
   423→    // 이미 존재하면 업데이트
   424→    for (let i = this.locals.length - 1; i >= 0; i--) {
   425→      if (this.locals[i].has(name)) {
   426→        this.locals[i].set(name, value);
   427→        return;
   428→      }
   429→    }
   430→
   431→    if (this.globals.has(name)) {
   432→      this.globals.set(name, value);
   433→      return;
   434→    }
   435→
   436→    // 새로 선언
   437→    const scope = this.locals[this.locals.length - 1];
   438→    scope.set(name, value);
   439→  }
   440→}
