    10→import { V3Executor, V3Value } from './v3-executor';
    11→import { V3Program } from './v3-parser';
    12→
    13→export interface V3BytecodeInstruction {
    14→  op: string;
    15→  arg?: number | string;
    16→  line?: number;
    17→}
    18→
    19→export interface V3JITCompiledFunc {
    20→  func: Function;
    21→  bytecode: V3BytecodeInstruction[];
    22→  callCount: number;
    23→  executionTime: number;
    24→  isHotPath: boolean;
    25→}
    26→
    27→export class V3JIT {
    28→  private compiledCache: Map<string, V3JITCompiledFunc> = new Map();
    29→  private hotPathThreshold: number = 10; // 10회 이상 호출 시 JIT 컴파일
    30→  private profilingData: Map<string, { callCount: number; totalTime: number }> = new Map();
    31→
    32→  /**
    33→   * Bytecode → JavaScript 함수로 컴파일
    34→   * @param bytecode V3 바이트코드 명령어 배열
    35→   * @param context 실행 컨텍스트 (변수, 함수 등)
    36→   * @returns 컴파일된 함수
    37→   */
    38→  compileBytecode(bytecode: V3BytecodeInstruction[], context: any = {}): Function {
    39→    // 캐시 키 생성
    40→    const cacheKey = this.generateCacheKey(bytecode);
    41→
    42→    // 캐시에 있으면 반환
    43→    if (this.compiledCache.has(cacheKey)) {
    44→      const cached = this.compiledCache.get(cacheKey)!;
    45→      cached.callCount++;
    46→      return cached.func;
    47→    }
    48→
    49→    // JIT 컴파일: Bytecode → JavaScript 코드
    50→    const jsCode = this.generateJavaScriptCode(bytecode, context);
    51→
    52→    // JavaScript 함수 생성
    53→    const compiledFunc = new Function('context', `
    54→      const stack = [];
    55→      const locals = new Map();
    56→
    57→      ${jsCode}
    58→
    59→      return stack.length > 0 ? stack[stack.length - 1] : null;
    60→    `);
    61→
    62→    // 캐시에 저장
    63→    this.compiledCache.set(cacheKey, {
    64→      func: compiledFunc,
    65→      bytecode,
    66→      callCount: 0,
    67→      executionTime: 0,
    68→      isHotPath: false,
    69→    });
