    87→      const executor = new V3Executor();
    88→      const result = executor.execute(program);
    89→
    90→      // 2단계: 프로파일링 데이터 수집
    91→      const jitStats = {
    92→        compiledCount: this.compiledCache.size,
    93→        cacheHits: this.getTotalCacheHits(),
    94→        totalTime: this.getTotalExecutionTime(),
    95→      };
    96→
    97→      return {
    98→        ...result,
    99→        jitStats,
   100→      };
