   137→          break;
   138→
   139→        case 'SUB':
   140→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a - b); }\n`;
   141→          break;
   142→
   143→        case 'MUL':
   144→          code += `  { const b = stack.pop(); const a = stack.pop(); stack.push(a * b); }\n`;
   145→          break;
