   246→          break;
   247→
   248→        case 'CALL':
   249→          code += `  // CALL to ${instr.arg} (인터프리터에서 처리)\n`;
   250→          break;
   251→
   252→        case 'RET':
   253→          code += `  return stack.length > 0 ? stack[stack.length - 1] : null;\n`;
   254→          break;
