   263→
   264→  /**
   265→   * 캐시 키 생성
   266→   */
   267→  private generateCacheKey(bytecode: V3BytecodeInstruction[]): string {
   268→    return bytecode.map((instr) => `${instr.op}:${instr.arg}`).join('|');
   269→  }
   270→
   271→  /**
   272→   * 통계 정보
   273→   */
   274→  getStats(): {
   275→    compiledFunctions: number;
   276→    cacheSize: number;
   277→    totalCalls: number;
   278→    averageCallCount: number;
   279→    hotPathCount: number;
   280→  } {
   281→    const entries = Array.from(this.compiledCache.values());
   282→    const totalCalls = entries.reduce((sum, e) => sum + e.callCount, 0);
   283→
   284→    return {
   285→      compiledFunctions: this.compiledCache.size,
   286→      cacheSize: entries.length,
   287→      totalCalls,
   288→      averageCallCount: entries.length > 0 ? totalCalls / entries.length : 0,
   289→      hotPathCount: entries.filter((e) => e.isHotPath).length,
   290→    };
   291→  }
   292→
   293→  /**
   294→   * 캐시 클리어
   295→   */
   296→  clearCache(): void {
   297→    this.compiledCache.clear();
   298→    this.profilingData.clear();
   299→  }
   300→
   301→  /**
   302→   * 핫패스 감지
   303→   */
   304→  private detectHotPath(funcKey: string): boolean {
   305→    const stats = this.profilingData.get(funcKey);
   306→    return stats ? stats.callCount >= this.hotPathThreshold : false;
   307→  }
   308→
   309→  private getTotalCacheHits(): number {
   310→    let hits = 0;
   311→    for (const cached of this.compiledCache.values()) {
   312→      hits += cached.callCount;
   313→    }
   314→    return hits;
   315→  }
   316→
   317→  private getTotalExecutionTime(): number {
   318→    let total = 0;
   319→    for (const cached of this.compiledCache.values()) {
   320→      total += cached.executionTime;
   321→    }
   322→    return total;
   323→  }
   324→}
   325→
   326→/**
   327→ * JIT 벤치마크
   328→ */
   329→export function benchmarkJIT() {
   330→  console.log('\n╔════════════════════════════════════════╗');
   331→  console.log('║ V3 JIT Compiler Benchmark              ║');
   332→  console.log('╚════════════════════════════════════════╝\n');
   333→
   334→  // 테스트 바이트코드: 1 + 2 + 3 + ... + 100
   335→  const bytecode: V3BytecodeInstruction[] = [];
   336→  for (let i = 1; i <= 100; i++) {
   337→    bytecode.push({ op: 'PUSH', arg: i });
   338→    if (i > 1) {
   339→      bytecode.push({ op: 'ADD' });
   340→    }
   341→  }
   342→
   343→  const jit = new V3JIT();
   344→
   345→  // 1회: 인터프리터 (Executor)
   346→  console.log('📊 실행 시간 비교\n');
   347→
   348→  // JIT 컴파일
   349→  console.time('JIT Compilation');
   350→  const jitFunc = jit.compileBytecode(bytecode);
   351→  console.timeEnd('JIT Compilation');
   352→
   353→  // JIT 함수 실행 (10,000회)
   354→  console.time('JIT Function Execution (10K calls)');
   355→  for (let i = 0; i < 10000; i++) {
   356→    jitFunc({});
   357→  }
   358→  console.timeEnd('JIT Function Execution (10K calls)');
   359→
   360→  // 통계
   361→  const stats = jit.getStats();
   362→  console.log('\n📈 JIT 통계\n');
   363→  console.log(`✅ 컴파일된 함수: ${stats.compiledFunctions}`);
   364→  console.log(`✅ 캐시 크기: ${stats.cacheSize}`);
   365→  console.log(`✅ 총 호출 수: ${stats.totalCalls}`);
   366→  console.log(`✅ 평균 호출 횟수: ${stats.averageCallCount.toFixed(2)}`);
   367→  console.log(`✅ 핫패스: ${stats.hotPathCount}`);
   368→
   369→  console.log('\n✨ JIT는 반복 실행되는 코드를 JavaScript 함수로 컴파일하여 성능 향상!');
   370→}
