     1→/**
     2→ * V3 Bytecode Generator - AST → Bytecode 변환 (V3-Compiler 개선 버전)
     3→ *
     4→ * 더 체계적인 바이트코드 생성
     5→ * - 스택 기반 명령어
     6→ * - 변수 주소 할당
     7→ * - 제어흐름 라벨링
     8→ */
     9→
    10→import { V3Program, V3Statement, V3Expr } from './v3-parser';
    11→import { V3BytecodeInstruction } from './v3-jit';
    12→
    13→export interface V3BytecodeContext {
    14→  instructions: V3BytecodeInstruction[];
    15→  variables: Map<string, number>;
    16→  functions: Map<string, number>;
    17→  labels: Map<string, number>;
    18→  nextVarAddr: number;
    19→  nextLabel: number;
    20→}
    21→
    22→export class V3BytecodeGenerator {
    23→  private context: V3BytecodeContext;
    24→
    25→  constructor() {
    26→    this.context = {
    27→      instructions: [],
    28→      variables: new Map(),
    29→      functions: new Map(),
    30→      labels: new Map(),
    31→      nextVarAddr: 0,
    32→      nextLabel: 0,
    33→    };
    34→  }
    35→
    36→  /**
    37→   * AST → Bytecode 변환
    38→   */
    39→  generate(program: V3Program): V3BytecodeInstruction[] {
    40→    for (const stmt of program.statements) {
    41→      this.generateStatement(stmt);
    42→    }
    43→
    44→    // 프로그램 끝
    45→    this.emit('HALT');
    46→
    47→    return this.context.instructions;
    48→  }
    49→
    50→  private generateStatement(stmt: V3Statement): void {
    51→    switch (stmt.type) {
    52→      case 'VarDecl': {
    53→        const varDecl = stmt as any;
    54→        const addr = this.allocateVar(varDecl.name);
    55→        this.generateExpr(varDecl.value);
    56→        this.emit('STORE', addr);
    57→        break;
    58→      }
    59→
    60→      case 'IfStmt': {
    61→        const ifStmt = stmt as any;
    62→        this.generateExpr(ifStmt.condition);
    63→
    64→        const falseLabel = this.createLabel();
    65→        const endLabel = this.createLabel();
    66→
    67→        this.emit('JMP_NOT', falseLabel);
    68→
    69→        // Then block
    70→        for (const s of ifStmt.thenBlock) {
    71→          this.generateStatement(s);
    72→        }
    73→
    74→        this.emit('JMP', endLabel);
    75→
    76→        // False label
    77→        this.resolveLabel(falseLabel);
    78→
    79→        // Else block
    80→        if (ifStmt.elseBlock) {
    81→          for (const s of ifStmt.elseBlock) {
    82→            this.generateStatement(s);
    83→          }
    84→        }
    85→
    86→        // End label
    87→        this.resolveLabel(endLabel);
    88→        break;
    89→      }
    90→
    91→      case 'ForLoop': {
    92→        const forLoop = stmt as any;
    93→        const varAddr = this.allocateVar(forLoop.variable);
    94→        const idxAddr = this.allocateVar(`__idx_${forLoop.variable}`);
    95→        const arrAddr = this.allocateVar(`__arr_${forLoop.variable}`);
    96→
    97→        // 배열 생성
    98→        this.generateExpr(forLoop.iterable);
    99→        this.emit('STORE', arrAddr);
   100→
   101→        // 인덱스 초기화
   102→        this.emit('PUSH', 0);
   103→        this.emit('STORE', idxAddr);
   104→
   105→        // 루프 시작
   106→        const loopStart = this.context.instructions.length;
   107→        const loopEnd = this.createLabel();
   108→
   109→        // 배열 길이 확인
   110→        this.emit('LOAD', arrAddr);
   111→        this.emit('ARR_LEN');
   112→        this.emit('LOAD', idxAddr);
   113→        this.emit('GT');
   114→        this.emit('JMP_NOT', loopEnd);
   115→
   116→        // 변수에 현재 값 할당
   117→        this.emit('LOAD', arrAddr);
   118→        this.emit('LOAD', idxAddr);
   119→        this.emit('ARR_GET');
   120→        this.emit('STORE', varAddr);
   121→
   122→        // 루프 본체
   123→        for (const s of forLoop.body) {
   124→          this.generateStatement(s);
   125→        }
   126→
   127→        // 인덱스 증가
   128→        this.emit('LOAD', idxAddr);
   129→        this.emit('PUSH', 1);
   130→        this.emit('ADD');
   131→        this.emit('STORE', idxAddr);
   132→
   133→        // 루프 재시작
   134→        this.emit('JMP', loopStart);
   135→
   136→        // 루프 끝
   137→        this.resolveLabel(loopEnd);
   138→        break;
   139→      }
   140→
   141→      case 'FuncDecl': {
   142→        const funcDecl = stmt as any;
   143→        const funcAddr = this.context.instructions.length;
   144→        this.context.functions.set(funcDecl.name, funcAddr);
   145→
   146→        // 함수 본체
   147→        for (const s of funcDecl.body) {
   148→          this.generateStatement(s);
   149→        }
   150→
   151→        // 기본 반환값
   152→        if (!this.lastIsReturn()) {
   153→          this.emit('PUSH', null);
   154→          this.emit('RET');
   155→        }
   156→        break;
   157→      }
   158→
   159→      case 'ReturnStmt': {
   160→        const returnStmt = stmt as any;
   161→        if (returnStmt.value) {
   162→          this.generateExpr(returnStmt.value);
   163→        } else {
   164→          this.emit('PUSH', null);
   165→        }
   166→        this.emit('RET');
   167→        break;
   168→      }
   169→
   170→      case 'ExprStmt': {
   171→        const exprStmt = stmt as any;
   172→        this.generateExpr(exprStmt.expr);
   173→        break;
   174→      }
   175→    }
   176→  }
   177→
   178→  private generateExpr(expr: V3Expr): void {
   179→    switch (expr.type) {
   180→      case 'Number': {
   181→        const numExpr = expr as any;
   182→        this.emit('PUSH', numExpr.value);
   183→        break;
   184→      }
   185→
   186→      case 'String': {
   187→        const strExpr = expr as any;
   188→        this.emit('PUSH', strExpr.value);
   189→        break;
   190→      }
   191→
   192→      case 'Bool': {
   193→        const boolExpr = expr as any;
   194→        this.emit('PUSH', boolExpr.value ? 1 : 0);
   195→        break;
   196→      }
   197→
   198→      case 'Identifier': {
   199→        const idExpr = expr as any;
   200→        const addr = this.context.variables.get(idExpr.name);
   201→        if (addr !== undefined) {
   202→          this.emit('LOAD', addr);
   203→        } else {
   204→          // 상수로 간주
   205→          this.emit('PUSH', idExpr.name);
   206→        }
   207→        break;
   208→      }
   209→
   210→      case 'BinaryOp': {
   211→        const binOp = expr as any;
   212→        this.generateExpr(binOp.left);
   213→        this.generateExpr(binOp.right);
   214→
   215→        switch (binOp.op) {
   216→          case '+':
   217→            this.emit('ADD');
   218→            break;
   219→          case '-':
   220→            this.emit('SUB');
   221→            break;
   222→          case '*':
   223→            this.emit('MUL');
   224→            break;
   225→          case '/':
   226→            this.emit('DIV');
   227→            break;
   228→          case '==':
   229→            this.emit('EQ');
   230→            break;
   231→          case '!=':
   232→            this.emit('NEQ');
   233→            break;
   234→          case '<':
   235→            this.emit('LT');
   236→            break;
   237→          case '<=':
   238→            this.emit('LTE');
   239→            break;
   240→          case '>':
   241→            this.emit('GT');
   242→            break;
   243→          case '>=':
   244→            this.emit('GTE');
   245→            break;
   246→          case 'AND':
   247→            this.emit('AND');
   248→            break;
   249→          case 'OR':
   250→            this.emit('OR');
   251→            break;
   252→        }
   253→        break;
   254→      }
   255→
   256→      case 'UnaryOp': {
   257→        const unaryOp = expr as any;
   258→        this.generateExpr(unaryOp.operand);
   259→        if (unaryOp.op === '-') {
   260→          this.emit('NEG');
   261→        }
   262→        break;
   263→      }
   264→
   265→      case 'ArrayLiteral': {
   266→        const arrLit = expr as any;
   267→        for (const elem of arrLit.elements) {
   268→          this.generateExpr(elem);
   269→        }
   270→        this.emit('ARR_NEW', arrLit.elements.length);
   271→        break;
   272→      }
   273→
   274→      case 'ArrayAccess': {
   275→        const arrAccess = expr as any;
   276→        this.generateExpr(arrAccess.array);
   277→        this.generateExpr(arrAccess.index);
   278→        this.emit('ARR_GET');
   279→        break;
   280→      }
   281→
   282→      case 'ArrayOp': {
   283→        const arrOp = expr as any;
   284→        this.generateExpr(arrOp.array);
   285→
   286→        switch (arrOp.op) {
   287→          case 'ARR_SUM':
   288→            this.emit('ARR_SUM');
   289→            break;
   290→          case 'ARR_AVG':
   291→            this.emit('ARR_AVG');
   292→            break;
   293→          case 'ARR_MAX':
   294→            this.emit('ARR_MAX');
   295→            break;
   296→          case 'ARR_MIN':
   297→            this.emit('ARR_MIN');
   298→            break;
   299→        }
   300→        break;
   301→      }
   302→
   303→      case 'FuncCall': {
   304→        const funcCall = expr as any;
   305→
   306→        // 빌트인 함수
   307→        if (funcCall.name === 'println') {
   308→          for (const arg of funcCall.args) {
   309→            this.generateExpr(arg);
   310→          }
   311→          // println은 특수 처리 필요
   312→          this.emit('CALL', -1); // -1 = println
   313→        } else {
   314→          // 사용자 정의 함수
   315→          const funcAddr = this.context.functions.get(funcCall.name);
   316→          if (funcAddr !== undefined) {
   317→            for (const arg of funcCall.args) {
   318→              this.generateExpr(arg);
   319→            }
   320→            this.emit('CALL', funcAddr);
   321→          }
   322→        }
   323→        break;
   324→      }
   325→
   326→      case 'Assignment': {
   327→        const assign = expr as any;
   328→        this.generateExpr(assign.value);
   329→        const addr = this.context.variables.get(assign.name);
   330→        if (addr !== undefined) {
   331→          this.emit('STORE', addr);
   332→        }
   333→        break;
   334→      }
   335→    }
   336→  }
   337→
   338→  private emit(op: string, arg?: any): void {
   339→    const instruction: V3BytecodeInstruction = { op, arg };
   340→    this.context.instructions.push(instruction);
   341→  }
   342→
   343→  private allocateVar(name: string): number {
   344→    if (this.context.variables.has(name)) {
   345→      return this.context.variables.get(name)!;
   346→    }
   347→
   348→    const addr = this.context.nextVarAddr++;
   349→    this.context.variables.set(name, addr);
   350→    return addr;
   351→  }
   352→
   353→  private createLabel(): string {
   354→    return `L${this.context.nextLabel++}`;
   355→  }
   356→
   357→  private resolveLabel(label: string): void {
   358→    this.context.labels.set(label, this.context.instructions.length);
   359→  }
   360→
   361→  private lastIsReturn(): boolean {
   362→    const last = this.context.instructions[this.context.instructions.length - 1];
   363→    return last && last.op === 'RET';
   364→  }
   365→}
   366→
   367→/**
   368→ * V3 프로그램 → Bytecode 변환
   369→ */
   370→export function programToBytecode(program: V3Program): V3BytecodeInstruction[] {
   371→  const gen = new V3BytecodeGenerator();
   372→  return gen.generate(program);
   373→}
